contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint value, uint preBalance) public payable {
        require(preBalance == address(c).balance, "preBalance must match c balance before the call");
        require(value <= preBalance, "success-path precondition: value does not exceed c balance");

        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdraw(value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint depositsAfter = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert(!reverted && depositsAfter == beforeDeposits && address(c).balance == preBalance - value);
    }

    receive() external payable {}
}

