pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 value, uint256 preBalance) internal {
        preBalance = address(c).balance;
        vm.assume(value <= preBalance);
        uint256 beforeDeposits;
        try c.depositsCount() returns (uint256 __r) { beforeDeposits = __r; } catch { return; }
        bool reverted;
        try c.withdraw(value) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 depositsAfter;
        try c.depositsCount() returns (uint256 __r) { depositsAfter = __r; } catch { return; }
        assertTrue(!reverted && depositsAfter == beforeDeposits && address(c).balance == preBalance - value);
    }

    function testFuzz_run(uint256 value, uint256 preBalance) public {
        _run(value, preBalance);
    }

    receive() external payable {}
}
